CREATE TABLE p(id INTEGER PRIMARY KEY, k INT, v INT, s TEXT);
CREATE TABLE q(id INTEGER PRIMARY KEY, k INT, v INT, s TEXT COLLATE NOCASE);
CREATE TABLE n(k INT, v INT, s TEXT);
CREATE TABLE e(k INT, v INT, s TEXT);
CREATE TABLE w(k INT PRIMARY KEY, v INT, s TEXT) WITHOUT ROWID;
INSERT INTO p VALUES (1, 1, 2, '1'), (2, 2, 3, 'b'), (3, NULL, 1, 'B'), (4, 4, NULL, NULL), (5, 1, 0, '2');
INSERT INTO q VALUES (1, 2, 2, 'B'), (2, 2, 0, 'a'), (3, 5, 1, '1'), (4, NULL, 4, NULL);
INSERT INTO n VALUES (1, 2, '2'), (NULL, 1, 'b'), (2, 2, NULL), (3, 0, 'A'), (1, NULL, '1');
INSERT INTO w VALUES (1, 1, 'a'), (2, 0, '2'), (6, NULL, NULL);
CREATE INDEX p_k ON p(k);
CREATE INDEX q_k ON q(k, v);
CREATE UNIQUE INDEX q_s ON q(s);
CREATE INDEX n_kv ON n(k, v);
CREATE INDEX n_v ON n(v);
CREATE INDEX w_v ON w(v);
CREATE INDEX e_k ON e(k);
SELECT count(*) FROM e AS a0 JOIN p AS a1 ON 0 RIGHT JOIN w AS a2 ON a0.k = a2.v;
SELECT count(*) FROM e AS a0 FULL JOIN w AS a2 ON a0.k = a2.v;
SELECT count(*) FROM p AS a0 FULL JOIN w AS a2 ON a0.k = a2.v;
SELECT a2.v FROM p AS a0 FULL JOIN w AS a2 ON a0.k = a2.v;
SELECT a2.v FROM w AS a2;
SELECT count(*) FROM w AS a2;
EXPLAIN QUERY PLAN SELECT count(*) FROM e AS a0 FULL JOIN w AS a2 ON a0.k = a2.v;
SELECT a2.k FROM e AS a0 FULL JOIN w AS a2 ON a0.k = a2.k WHERE EXISTS (SELECT 1 FROM n AS s1 WHERE (SELECT count(*) FROM e AS s2 JOIN p AS s3 ON s2.k = s3.k WHERE s3.k IS NULL) < s1.v AND s1.k = a2.k);
SELECT a0.k, a0.v, a1.k, a1.v, a2.k, a2.v FROM e AS a0 LEFT JOIN n AS a1 ON a0.k = a1.k RIGHT JOIN w AS a2 ON a1.k = a2.k WHERE EXISTS (SELECT 1 FROM n AS s1 WHERE (SELECT count(*) FROM e AS s2 JOIN p AS s3 ON s2.k = s3.k WHERE s3.k IS NULL) < s1.v AND s1.k = a2.k);
EXPLAIN QUERY PLAN SELECT a0.k, a0.v, a1.k, a1.v, a2.k, a2.v FROM e AS a0 LEFT JOIN n AS a1 ON a0.k = a1.k RIGHT JOIN w AS a2 ON a1.k = a2.k WHERE EXISTS (SELECT 1 FROM n AS s1 WHERE (SELECT count(*) FROM e AS s2 JOIN p AS s3 ON s2.k = s3.k WHERE s3.k IS NULL) < s1.v AND s1.k = a2.k);
SELECT a1.k, a2.k FROM p AS a1 FULL JOIN q AS a2 ON 0 WHERE (EXISTS (SELECT 1 FROM p AS s4 JOIN n AS s5 ON s4.k = s5.k WHERE s4.v) OR a2.k IS NULL);
EXPLAIN QUERY PLAN SELECT a1.k, a2.k FROM p AS a1 FULL JOIN q AS a2 ON 0 WHERE (EXISTS (SELECT 1 FROM p AS s4 JOIN n AS s5 ON s4.k = s5.k WHERE s4.v) OR a2.k IS NULL);
SELECT a0.k, a2.k FROM p AS a0 RIGHT JOIN q AS a2 ON 0 WHERE (SELECT sum(s3.v) FROM (SELECT k, v, s FROM p WHERE 1) AS s3 WHERE EXISTS (SELECT 1 FROM p AS s4 WHERE a0.v <> s3.k) AND s3.k <= a2.s) < a2.k;
SELECT a0.k, a0.v, a1.k, a1.v, a2.k, a2.v FROM p AS a0 JOIN p AS a1 ON EXISTS (SELECT 1 FROM q AS s1 WHERE NOT EXISTS (SELECT 1 FROM p AS s2 WHERE s2.v < s2.k)) RIGHT JOIN q AS a2 ON a1.k = a2.k WHERE (SELECT sum(s3.v) FROM (SELECT k, v, s FROM p WHERE 1) AS s3 WHERE EXISTS (SELECT 1 FROM p AS s4 WHERE a0.v <> s3.k) AND s3.k <= a2.s) < a2.k;
SELECT a0.k, a2.k FROM p AS a0 FULL JOIN q AS a2 ON 0 WHERE (SELECT sum(s3.v) FROM (SELECT k, v, s FROM p WHERE 1) AS s3 WHERE EXISTS (SELECT 1 FROM p AS s4 WHERE a0.v <> s3.k) AND s3.k <= a2.s) < a2.k;
EXPLAIN QUERY PLAN SELECT a0.k, a2.k FROM p AS a0 FULL JOIN q AS a2 ON 0 WHERE (SELECT sum(s3.v) FROM (SELECT k, v, s FROM p WHERE 1) AS s3 WHERE EXISTS (SELECT 1 FROM p AS s4 WHERE a0.v <> s3.k) AND s3.k <= a2.s) < a2.k;
EXPLAIN SELECT a0.k, a2.k FROM p AS a0 FULL JOIN q AS a2 ON 0 WHERE (SELECT sum(s3.v) FROM (SELECT k, v, s FROM p WHERE 1) AS s3 WHERE EXISTS (SELECT 1 FROM p AS s4 WHERE a0.v <> s3.k) AND s3.k <= a2.s) < a2.k;
ANALYZE;
SELECT a0.k, a0.v, a1.k, a1.v, a2.k, a2.v FROM p AS a0 CROSS JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE (SELECT min(s1.k) FROM p AS s1 WHERE a0.k < NULL) IS NOT (a2.k - a2.k);
SELECT a0.k, a1.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k WHERE (SELECT min(s1.k) FROM p AS s1 WHERE a0.k < NULL) IS NOT NULL;
EXPLAIN QUERY PLAN SELECT a0.k, a1.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k WHERE (SELECT min(s1.k) FROM p AS s1 WHERE a0.k < NULL) IS NOT NULL;
